INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, '¿Cuál palabra falta? ''El tipo de cambio del dólar hoy es 20.4, _______ . (今天的美金汇率是 20.4，又_______。)', 'opcion_multiple', '["subió", "bajó", "se mantuvo", "cambió"]', 'subió', '又 (yòu) implica ''otra vez'' o ''además''. ''Subió'' (shàng shēng) es una opción lógica.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, '¿Cuál palabra falta? ''En casi todas las casas chinas se acostumbra beber _______ . (几乎在所有的中国人家里都习惯喝 _______ 。)', 'opcion_multiple', '["té", "café", "leche", "agua"]', 'té', '茶 (chá) = té. Es una costumbre muy arraigada en China.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, '¿Cuál palabra falta? ''Cada lugar tiene sus propias _______ . (每个地方都有他们自己的_______。)', 'opcion_multiple', '["costumbres", "personas", "edificios", "animales"]', 'costumbres', '习惯 (xíguàn) = costumbres/hábitos.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, '¿Cuál palabra falta? ''Mucha gente gusta _______ ropa vieja. (很多人喜欢_______旧了，不要的衣服。)', 'opcion_multiple', '["donar", "guardar", "vender", "tirar"]', 'donar', '捐 (juān) = donar. ''Donar ropa vieja'' es una práctica común.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, '¿Cuál palabra falta? ''Los chinos prefieren el té con _______ fresca. (中国人喝茶喜欢用新鲜的_______ 。)', 'opcion_multiple', '["hojas", "agua", "leche", "azúcar"]', 'hojas', '茶叶 (cháyè) = hojas de té.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, '¿Cuál palabra falta? ''_______ es la llave para abrir corazones. (_______是打开人与人之间的心灵的一把钥匙。)', 'opcion_multiple', '["La risa", "La comida", "La comunicación", "El dinero"]', 'La comunicación', '交流 (jiāoliú) = comunicación/interacción. Es una metáfora sobre conexión humana.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, '¿Cuál palabra falta? ''El alimento principal en China es _______, en México es _______ . (中国人的主粮是_______，墨西哥人的主粮是_______。)', 'opcion_multiple', '["arroz / tortilla", "noodles / frijoles", "pan / arroz", "arroz / maíz"]', 'arroz / tortilla', '米饭 (mǐfàn) = arroz cocido. Tortilla es un alimento básico en México.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, '¿Cuál palabra falta? ''La hora de comer en China es más _______, en Occidente es más _______ . (中国人的进食时间比较______，西方人进食时间比较_____ 。)', 'opcion_multiple', '["flexible / fija", "fija / flexible", "tarde / temprano", "temprano / tarde"]', 'fija / flexible', '比较 (bǐjiào) = más... que. This implies a comparison of characteristics.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, '¿Cuál palabra falta? ''Perdón, no traigo _______ , solo un billete de 500 pesos. (对不起，我没带_______，只带了一张 500比索的纸币。)', 'opcion_multiple', '["monedas", "tarjeta", "dinero", "cambio"]', 'monedas', '零钱 (língqián) = cambio/monedas sueltas.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, '¿Cuál palabra falta? ''_______ es importante para el desarrollo del mundo. (_______是越来越重要对于世界的发展。)', 'opcion_multiple', '["El idioma", "La tecnología", "La economía", "La educación"]', 'El idioma', '语言 (yǔyán) = idioma/lenguaje.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Ordena: ''desde / el / hotel / hay / una / calle / muy / ancha.'' (从酒店出来有一条很宽的大马路。)', 'opcion_multiple', '["Desde el hotel hay una calle muy ancha.", "Hay una calle muy ancha desde el hotel.", "Una calle muy ancha hay desde el hotel.", "Desde el hotel una calle muy ancha hay."]', 'Desde el hotel hay una calle muy ancha.', '从 (cóng) = desde. 酒店 (jiǔdiàn) = hotel. 出来 (chūlái) = salir. 有 (yǒu) = hay. 一条 (yī tiáo) = una (calle). 很宽 (hěn kuān) = muy ancha. 大马路 (dà mǎlù) = calle principal.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Ordena: ''debemos / anticipar / para / volar / nosotros / comprar / el / boleto.'' (我们要提前买飞机票。)', 'opcion_multiple', '["Debemos comprar el boleto para volar con anticipación.", "Para volar, debemos comprar el boleto con anticipación.", "Comprar el boleto con anticipación es para volar.", "Con anticipación, debemos comprar el boleto para volar."]', 'Debemos comprar el boleto para volar con anticipación.', '要 (yào) = deber/querer. 提前 (tíqián) = con anticipación. 买 (mǎi) = comprar. 飞机票 (fēijīpiào) = boleto de avión.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Ordena: ''desde / pequeño / yo / tengo / un / sueño / viajar / a / China.'' (我从小就有个去中国的旅游梦想。)', 'opcion_multiple', '["Desde pequeño yo tengo un sueño de viajar a China.", "Tengo un sueño de viajar a China desde pequeño.", "Un sueño de viajar a China tengo desde pequeño.", "Yo desde pequeño tengo un sueño de viajar a China."]', 'Desde pequeño yo tengo un sueño de viajar a China.', '从小 (cóng xiǎo) = desde pequeño. 旅游梦想 (lǚyóu mèngxiǎng) = sueño de viaje.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Ordena: ''habitación / para / rentar / usualmente / se / paga / un / depósito / de / un / mes.'' (通常租房子要交一个月押金。)', 'opcion_multiple', '["Para rentar una habitación usualmente se paga un depósito de un mes.", "Usualmente se paga un mes de depósito para rentar una habitación.", "Un mes de depósito se paga usualmente para rentar una habitación.", "Para rentar, usualmente pagas un mes de depósito."]', 'Para rentar una habitación usualmente se paga un depósito de un mes.', '通常 (tōngcháng) = usualmente. 租房子 (zū fángzi) = rentar una casa/habitación. 押金 (yājīn) = depósito.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Ordena: ''cinco / hoteles / estrellas / usualmente / proveen / desayuno / gratis / y / muy / bueno / servicio.'' (五星级酒店一般提供很好的免费早餐和服务。)', 'opcion_multiple', '["Los hoteles cinco estrellas usualmente proveen desayuno gratis y muy buen servicio.", "Usualmente, los hoteles cinco estrellas proveen desayuno gratis y muy buen servicio.", "Desayuno gratis y muy buen servicio proveen usualmente los hoteles cinco estrellas.", "Proveen usualmente desayuno gratis y muy buen servicio los hoteles cinco estrellas."]', 'Los hoteles cinco estrellas usualmente proveen desayuno gratis y muy buen servicio.', '五星级 (wǔ xīng jí) = cinco estrellas. 一般 (yībān) = usualmente/generalmente. 提供 (tígōng) = proveer/ofrecer. 免费 (miǎnfèi) = gratis.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Ordena: ''puedes / pagar / con /微信 / en / un / restaurante / aquí.'' (在这里你可以用微信支付。)', 'opcion_multiple', '["Aquí puedes pagar con WeChat en un restaurante.", "Puedes pagar con WeChat en un restaurante aquí.", "Con WeChat puedes pagar en un restaurante aquí.", "Aquí, en un restaurante, puedes pagar con WeChat."]', 'Aquí puedes pagar con WeChat en un restaurante.', '这里 (zhèlǐ) = aquí. 微信 (wēixìn) = WeChat. 支付 (zhīfù) = pagar.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Ordena: ''por / favor / dime / cuánto / dinero / queda / en / tu / tarjeta.'' (请问你卡里还剩下多少钱？)', 'opcion_multiple', '["Por favor, dime cuánto dinero queda en tu tarjeta.", "Dime por favor cuánto dinero queda en tu tarjeta.", "Cuánto dinero queda en tu tarjeta, por favor dime.", "Por favor dime cuánto dinero queda en tu tarjeta."]', 'Por favor, dime cuánto dinero queda en tu tarjeta.', '请问 (qǐngwèn) = por favor/dime. 卡里 (kǎ lǐ) = en la tarjeta. 还剩下 (hái shèngxià) = aún queda/quedan.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Ordena: ''generalmente / para / rentar / una / casa / necesitas / pagar / un / mes / de / depósito.'' (一般来说，租房子需要付一个月的押金。)', 'opcion_multiple', '["Generalmente, para rentar una casa necesitas pagar un mes de depósito.", "Para rentar una casa, generalmente necesitas pagar un mes de depósito.", "Necesitas pagar un mes de depósito generalmente para rentar una casa.", "Generalmente necesitas pagar un mes de depósito para rentar una casa."]', 'Generalmente, para rentar una casa necesitas pagar un mes de depósito.', '一般来说 (yībān lái shuō) = generalmente/habitualmente. 付 (fù) = pagar.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Ordena: ''quiero / abrir / una / cuenta / bancaria / , / ¿ / qué / trámites / debo / hacer / ?'' (我想开一个银行账户，要办什么手续？)', 'opcion_multiple', '["Quiero abrir una cuenta bancaria, ¿qué trámites debo hacer?", "¿Qué trámites debo hacer para abrir una cuenta bancaria?", "Para abrir una cuenta bancaria, ¿qué trámites debo hacer?", "Debo hacer qué trámites para abrir una cuenta bancaria."]', 'Quiero abrir una cuenta bancaria, ¿qué trámites debo hacer?', '开 (kāi) = abrir. 银行账户 (yínháng zhànghù) = cuenta bancaria. 手续 (shǒuxù) = trámites/procedimientos.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Ordena: ''el / aeropuerto / está / muy / lejos / de / aquí / , / debes / ir / en / taxi.'' (机场离这里很远，你必须坐出租车去。)', 'opcion_multiple', '["El aeropuerto está muy lejos de aquí, debes ir en taxi.", "Debes ir en taxi porque el aeropuerto está muy lejos de aquí.", "Está muy lejos el aeropuerto de aquí, así que irás en taxi.", "Irás en taxi al aeropuerto porque está muy lejos."]', 'El aeropuerto está muy lejos de aquí, debes ir en taxi.', '机场 (jīchǎng) = aeropuerto. 离 (lí) = distancia. 很远 (hěn yuǎn) = muy lejos. 必须 (bìxū) = debes/deberás. 出租车 (chūzūchē) = taxi.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Traduce: ''Generally, to rent a house you need to pay one month deposit.'' (一般来说，租房子需要付一个月的押金。)', 'opcion_multiple', '["Generalmente, para rentar una casa necesitas pagar un mes de depósito.", "Rentar una casa es caro.", "No necesitas pagar depósito.", "Pagas el depósito al final."]', 'Generalmente, para rentar una casa necesitas pagar un mes de depósito.', '一般来说 (yībān lái shuō) = generalmente. 租 (zū) = rentar. 付 (fù) = pagar. 押金 (yājīn) = depósito.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Traduce: ''I want to open a bank account, what procedures must I do?'' (我想开一个银行账户，要办什么手续？)', 'opcion_multiple', '["Quiero abrir una cuenta bancaria, ¿qué trámites debo hacer?", "Necesito dinero.", "Voy al banco.", "Tengo una cuenta."]', 'Quiero abrir una cuenta bancaria, ¿qué trámites debo hacer?', '开 (kāi) = abrir. 银行账户 (yínháng zhànghù) = cuenta bancaria. 手续 (shǒuxù) = trámites.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Traduce: ''Language is increasingly important for the development of the world.'' (语言对世界发展越来越重要。)', 'opcion_multiple', '["El idioma es cada vez más importante para el desarrollo del mundo.", "El idioma no es importante.", "El mundo no necesita idiomas.", "El desarrollo no necesita idiomas."]', 'El idioma es cada vez más importante para el desarrollo del mundo.', '语言 (yǔyán) = idioma/lenguaje. 对 (duì) = para. 发展 (fāzhǎn) = desarrollo. 越来越 (yuèláiyuè) = cada vez más.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Traduce: ''The airport is very far from here, you have to go by taxi.'' (机场离这里很远，你必须坐出租车去。)', 'opcion_multiple', '["El aeropuerto está muy lejos de aquí, debes ir en taxi.", "Puedes ir al aeropuerto caminando.", "El aeropuerto está cerca.", "Toma el autobús al aeropuerto."]', 'El aeropuerto está muy lejos de aquí, debes ir en taxi.', '机场 (jīchǎng) = aeropuerto. 离 (lí) = distancia. 很远 (hěn yuǎn) = muy lejos. 必须 (bìxū) = debes. 出租车 (chūzūchē) = taxi.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Traduce: ''It takes me 15 minutes to walk from the hotel to the subway station.'' (从酒店走到地铁站要15分钟。)', 'opcion_multiple', '["Tardo 15 minutos en caminar desde el hotel hasta la estación de metro.", "La estación de metro está a 15 minutos.", "Camino 15 minutos.", "El hotel está lejos."]', 'Tardo 15 minutos en caminar desde el hotel hasta la estación de metro.', '从 (cóng) = desde. 走 (zǒu) = caminar. 地铁站 (dìtiě zhàn) = estación de metro. 要 (yào) = tomar/tardar (tiempo).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Traduce: ''Each place has its own dialect and way of life.'' (每个地方都有他们自己的方言和生活習慣。)', 'opcion_multiple', '["Cada lugar tiene su propio dialecto y forma de vivir.", "Todos los lugares son iguales.", "No hay diferencias culturales.", "El dialecto es lo mismo en todas partes."]', 'Cada lugar tiene su propio dialecto y forma de vivir.', '每个 (měi gè) = cada. 他们自己的 (tāmen zìjǐ de) = su propio. 生活習慣 (shēnghuó xíguàn) = hábitos de vida.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Traduce: ''The exchange rate of the dollar today is 20.4, it went up again.'' (今天的美金汇率是 20.4，又涨了。)', 'opcion_multiple', '["El tipo de cambio del dólar hoy es 20.4, subió otra vez.", "El tipo de cambio del dólar hoy es 20.4, bajó otra vez.", "El tipo de cambio del dólar hoy es 20.4, se mantuvo.", "El tipo de cambio del dólar hoy es 20.4, cambió."]', 'El tipo de cambio del dólar hoy es 20.4, subió otra vez.', '又 (yòu) = otra vez/además. 涨 (zhǎng) = subir (precios/tipo de cambio).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Traduce: ''In almost every Chinese household, they are used to drinking tea.'' (几乎在所有的中国人家里都习惯喝茶。)', 'opcion_multiple', '["En casi todas las casas chinas se acostumbra beber té.", "En todas las casas chinas beben té.", "En casi todas las casas chinas se come arroz.", "A los chinos no les gusta el té."]', 'En casi todas las casas chinas se acostumbra beber té.', '几乎 (jīhū) = casi. 所有的 (suǒyǒu de) = todos/as. 习惯 (xíguàn) = acostumbrarse/hábito. 喝茶 (hē chá) = beber té.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Traduce: ''It takes 15 minutes to walk from the hotel to the subway station.'' (从酒店走到地铁站要15分钟。)', 'opcion_multiple', '["Tarda 15 minutos en caminar desde el hotel hasta la estación de metro.", "Camina 15 minutos.", "Hotel a metro son 15 minutos.", "Metro está 15 minutos."]', 'Tarda 15 minutos en caminar desde el hotel hasta la estación de metro.', '从 (cóng) = desde. 走 (zǒu) = caminar. 要 (yào) = tomar/tardar (tiempo). 分钟 (fēnzhōng) = minutos.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (12, 'Traduce: ''Every place has its own dialect and way of life.'' (每个地方都有他们自己的方言和生活習慣。)', 'opcion_multiple', '["Cada lugar tiene su propio dialecto y forma de vivir.", "No hay diferencias culturales.", "El dialecto es lo mismo en todas partes.", "Cada lugar tiene la misma cultura."]', 'Cada lugar tiene su propio dialecto y forma de vivir.', '每个 (měi gè) = cada. 他们自己的 (tāmen zìjǐ de) = su propio. 方言 (fāngyán) = dialecto. 生活習慣 (shēnghuó xíguàn) = hábitos de vida.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Cuál es el significado de ''汇率'' en el contexto económico?', 'opcion_multiple', '["Inflación", "Tipo de cambio", "Tasa de interés", "Producto Interno Bruto"]', 'Tipo de cambio', '汇率 (huìlǜ) = tipo de cambio monetario.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué implica ''几乎'' en una oración?', 'opcion_multiple', '["Totalidad", "Casi, casi todo", "Nada", "Poca cantidad"]', 'Casi, casi todo', '几乎 (jīhū) = casi, prácticamente.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Cuál es la diferencia de grado entre ''很'' y ''非常''?', 'opcion_multiple', '["Ninguna", "Muy vs. extremadamente", "Formal vs. informal", "Positivo vs. negativo"]', 'Muy vs. extremadamente', '很 (hěn) = muy. 非常 (fēicháng) = muy/extremadamente, con más intensidad.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué función tiene ''又'' en ''又涨了''?', 'opcion_multiple', '["Negación", "Condicional", "Repetición o adición", "Concesión"]', 'Repetición o adición', '又 (yòu) = otra vez, además.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''越来越''?', 'opcion_multiple', '["Cada vez más", "Cada vez menos", "Igual", "Rápido"]', 'Cada vez más', '越来越 (yuèláiyuè) = cada vez más.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Cuál es el uso de ''要'' en ''要办什么手续''?', 'opcion_multiple', '["Voluntad", "Necesidad", "Futuro", "Todos los anteriores"]', 'Todos los anteriores', '要 (yào) puede implicar necesidad o intención futura en este contexto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué indica ''必须'' en una oración?', 'opcion_multiple', '["Opción", "Sugerencia", "Obligación", "Deseo"]', 'Obligación', '必须 (bìxū) = debe, obligatorio.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué tipo de relación establece ''但是''?', 'opcion_multiple', '["Causal", "Temporal", "Condicional", "Contrastiva"]', 'Contrastiva', '但是 (dànshì) = pero, sin embargo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''一般来说''?', 'opcion_multiple', '["En resumen", "Generalmente", "De repente", "Por casualidad"]', 'Generalmente', '一般来说 (yībān lái shuō) = en general, habitualmente.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué implica ''从...到...''?', 'opcion_multiple', '["Posesión", "Comparación", "Rango o dirección", "Tiempo"]', 'Rango o dirección', '从 (cóng) ... 到 (dào) ... = desde ... hasta ... (espacio o tiempo).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Cuál es la estructura correcta para ''Es importante que...''?', 'opcion_multiple', '["...是重要的", "...重要", "重要是...", "...是重要"]', '...是重要的', '是 (shì) + adjetivo + 的 (de) para enfatizar. ''...是重要的''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Cómo se forma el pretérito con ''了''?', 'opcion_multiple', '["Verbo + 了", "Sujeto + 了 + verbo", "Verbo + 了 + objeto", "A y C son correctas"]', 'A y C son correctas', '了 (le) marca la acción como completada. Se puede usar como ''V了'' o ''V了O''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué función tiene ''被''?', 'opcion_multiple', '["Activo", "Pasivo", "Reflexivo", "Recíproco"]', 'Pasivo', '被 (bèi) introduce la voz pasiva.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''把'' en una oración?', 'opcion_multiple', '["Tener", "Sostener", "Manipular/objetivo directo anticipado", "Hacia"]', 'Manipular/objetivo directo anticipado', '把 (bǎ) introduce una estructura donde el objeto directo se menciona antes del verbo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Cuál es la función de ''得'' en ''跑得快''?', 'opcion_multiple', '["Poseer", "Conectar verbo y complemento de grado", "Tiempo", "Condicional"]', 'Conectar verbo y complemento de grado', '得 (de) conecta un verbo con un complemento que indica grado o modo (rapidez, habilidad).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Cómo se expresa ''tener que'' o ''deber''? (Nivel 6)', 'opcion_multiple', '["要", "必须", "需要", "Todos los anteriores"]', 'Todos los anteriores', 'Todas las opciones pueden expresar obligación, con matices.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué estructura se usa para ''ser difícil para alguien hacer algo''?', 'opcion_multiple', '["对...很难", "...很难对", "很难...对", "对...很难..."]', '对...很难...', '对 (duì) + alguien + 很难 (hěn nán) + hacer algo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''以来''?', 'opcion_multiple', '["En adelante", "Desde entonces", "Antes", "Hasta"]', 'Desde entonces', '以来 (yǐlái) = desde (un punto en el tiempo).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Cómo se dice ''Cuanto más... tanto más...''?', 'opcion_multiple', '["越...越...", "更...更...", "最...最...", "A y B"]', '越...越...', '越 (yuè) ... 越 (yuè) ... = cuanto más ... tanto más ... (proporcionalidad).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué indica ''才''?', 'opcion_multiple', '["Solo hasta", "Demasiado", "Rápido", "Tarde"]', 'Solo hasta', '才 (cái) a menudo implica ''solo hasta que'' o ''recién''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''一帆风顺''?', 'opcion_multiple', '["Lluvia intensa", "Problemas", "Buena suerte, sin obstáculos", "Viento fuerte"]', 'Buena suerte, sin obstáculos', '一帆风顺 (yī fān fēng shùn) = navegar con viento favorable, éxito sin contratiempos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''画蛇添足''?', 'opcion_multiple', '["Dibujar bien", "Hacer algo innecesario", "Tener talento", "Ser hábil"]', 'Hacer algo innecesario', '画蛇添足 (huà shé tiān zú) = dibujar una serpiente y añadirle patas, arruinar algo bueno con detalles innecesarios.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''塞翁失马''?', 'opcion_multiple', '["Pérdida irreparable", "Beneficio inesperado", "Cambio repentino", "Mala suerte"]', 'Beneficio inesperado', '塞翁失马 (sài wēng shī mǎ) = la historia del anciano que perdió su caballo, que luego resultó en algo bueno. ''No hay maldad que por bien no venga''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''对牛弹琴''?', 'opcion_multiple', '["Tocar música", "Hablar con sabios", "Hablar en vano", "Ser musical"]', 'Hablar en vano', '对牛弹琴 (duì niú tán qín) = tocar el qin a una vaca, predicar en el desierto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''亡羊补牢''?', 'opcion_multiple', '["Cuidar bien", "Arrepentirse", "Remediar una falla a tiempo", "Cerrar puertas"]', 'Remediar una falla a tiempo', '亡羊补牢 (wáng yáng bǔ láo) = perder una oveja y reparar el cerco, remediar una falla a tiempo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''守株待兔''?', 'opcion_multiple', '["Estar alerta", "Esperar oportunidad", "Esfuerzo constante", "Pereza, esperar suerte"]', 'Pereza, esperar suerte', '守株待兔 (shǒu zhū dài tù) = esperar que algo bueno ocurra de nuevo sin esfuerzo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''水滴石穿''?', 'opcion_multiple', '["Agua débil", "Roca fuerte", "Paciencia y persistencia", "Diluvio"]', 'Paciencia y persistencia', '水滴石穿 (shuǐ dī shí chuān) = la gota que talla la piedra, constancia logra metas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''班门弄斧''?', 'opcion_multiple', '["Ser hábil", "Presumir", "Mostrar respeto", "Presumir frente a un experto"]', 'Presumir frente a un experto', '班门弄斧 (bān mén nòng fǔ) = manejar un hacha frente al maestro Ban, presumir de habilidad frente a un experto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''狐假虎威''?', 'opcion_multiple', '["Astucia", "Poder falso", "Miedo", "Valentía"]', 'Poder falso', '狐假虎威 (hú jiǎ hǔ wēi) = el zorro que presume de la ferocidad del tigre, valerse de la autoridad ajena.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (13, '¿Qué significa ''胸有成竹''?', 'opcion_multiple', '["Tener miedo", "Tener un plan", "Carecer de ideas", "Tener celos"]', 'Tener un plan', '胸有成竹 (xiōng yǒu chéng zhú) = tener un plan claro en la mente.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'What is your name?', 'opcion_multiple', '["What is your name?", "How are you?", "Where are you from?", "What time is it?"]', 'What is your name?', 'Pregunta directa para conocer el nombre.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Where do you live?', 'opcion_multiple', '["Where do you work?", "Where do you live?", "What do you do?", "How old are you?"]', 'Where do you live?', 'Pregunta sobre el lugar donde reside la persona.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'How old are you?', 'opcion_multiple', '["How tall are you?", "How old are you?", "How much is it?", "How do you do?"]', 'How old are you?', 'Pregunta sobre la edad.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'What time is it?', 'opcion_multiple', '["What day is it?", "What time is it?", "When is your birthday?", "How is the weather?"]', 'What time is it?', 'Pregunta sobre la hora actual.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'How are you?', 'opcion_multiple', '["How are you?", "How do you do?", "Nice to meet you.", "Good morning."]', 'How are you?', 'Pregunta común de cortesía sobre el estado de ánimo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'What do you do?', 'opcion_multiple', '["What do you do?", "What are you doing?", "What did you do?", "What will you do?"]', 'What do you do?', 'Pregunta sobre la ocupación o profesión.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Where are you from?', 'opcion_multiple', '["Where are you from?", "Where do you come from?", "Where were you born?", "All of the above"]', 'All of the above', 'Todas son formas válidas de preguntar por el origen.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Nice to meet you.', 'opcion_multiple', '["Nice to meet you.", "How do you do?", "Goodbye.", "Have a nice day."]', 'Nice to meet you.', 'Frase utilizada al conocer a alguien por primera vez.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Translate ''Casa'' to English.', 'opcion_multiple', '["House", "Flat", "Apartment", "Building"]', 'House', 'La traducción directa de ''casa'' es ''house''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Translate ''Comer'' to English.', 'opcion_multiple', '["To drink", "To cook", "To eat", "To prepare"]', 'To eat', 'La traducción directa de ''comer'' es ''to eat''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Translate ''Libro'' to English.', 'opcion_multiple', '["Magazine", "Newspaper", "Book", "Letter"]', 'Book', 'La traducción directa de ''libro'' es ''book''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Translate ''Perro'' to English.', 'opcion_multiple', '["Cat", "Bird", "Fish", "Dog"]', 'Dog', 'La traducción directa de ''perro'' es ''dog''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Translate ''Agua'' to English.', 'opcion_multiple', '["Water", "Milk", "Juice", "Coffee"]', 'Water', 'La traducción directa de ''agua'' es ''water''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Translate ''Familia'' to English.', 'opcion_multiple', '["Family", "Friends", "Parents", "Siblings"]', 'Family', 'La traducción directa de ''familia'' es ''family''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Translate ''Trabajo'' to English.', 'opcion_multiple', '["Job", "Work", "Task", "Both A and B"]', 'Both A and B', '''Trabajo'' puede ser ''job'' (empleo) o ''work'' (trabajo como acción).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Translate ''Escuela'' to English.', 'opcion_multiple', '["School", "University", "College", "Institute"]', 'School', 'La traducción directa de ''escuela'' es ''school''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Choose the correct verb: ''I _____ English.''', 'opcion_multiple', '["am speak", "speaks", "am speaking", "speak"]', 'speak', 'Usamos el verbo en presente simple: ''I speak English''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Choose the correct article: ''I have _____ apple.''', 'opcion_multiple', '["a", "an", "the", "no article"]', 'an', 'Usamos ''an'' porque ''apple'' comienza con vocal.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Choose the correct possessive adjective: ''_____ book is red.''', 'opcion_multiple', '["My", "Mine", "I", "Me"]', 'My', 'Usamos ''my'' antes del sustantivo: ''My book is red''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Choose the correct pronoun: ''_____ is my friend.''', 'opcion_multiple', '["He", "Him", "His", "Her"]', 'He', 'Usamos ''He'' como sujeto: ''He is my friend''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Choose the correct negative form: ''I _____ like coffee.''', 'opcion_multiple', '["not like", "don''t likes", "doesn''t like", "don''t like"]', 'don''t like', 'Usamos ''don''t'' con ''I'': ''I don''t like coffee''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Choose the correct question word: ''_____ is your name?''', 'opcion_multiple', '["Where", "What", "When", "How"]', 'What', 'Usamos ''what'' para preguntar por el nombre: ''What is your name?''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Choose the correct form: ''She _____ to the cinema yesterday.''', 'opcion_multiple', '["go", "goes", "went", "going"]', 'went', 'Usamos el pasado simple: ''She went to the cinema yesterday''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Choose the correct preposition: ''The book is _____ the table.''', 'opcion_multiple', '["in", "on", "at", "under"]', 'on', 'Usamos ''on'' para indicar posición encima: ''on the table''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'What do you say when you meet someone for the first time?', 'opcion_multiple', '["Goodbye", "How are you?", "Nice to meet you.", "See you later."]', 'Nice to meet you.', 'Esta frase es apropiada para el primer encuentro.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'What do you say when you leave?', 'opcion_multiple', '["Hello", "Goodbye", "How are you?", "Please sit down."]', 'Goodbye', 'Frase utilizada para despedirse.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'What do you say to ask for help?', 'opcion_multiple', '["Thank you", "Please", "Excuse me", "I''m sorry"]', 'Excuse me', 'Frase común para llamar la atención o pedir ayuda.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'What do you say to thank someone?', 'opcion_multiple', '["Excuse me", "You''re welcome", "Thank you", "Please"]', 'Thank you', 'Frase utilizada para mostrar gratitud.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'What do you say to apologize?', 'opcion_multiple', '["Thank you", "Please", "Excuse me", "I''m sorry"]', 'I''m sorry', 'Frase utilizada para disculparse.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'What do you say to respond to ''Thank you''?', 'opcion_multiple', '["Thank you", "You''re welcome", "Excuse me", "Please"]', 'You''re welcome', 'Frase común para responder a una gratitud.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'How do you ask for directions?', 'opcion_multiple', '["How are you?", "What time is it?", "Excuse me, where is...?", "Nice to meet you."]', 'Excuse me, where is...?', 'Frase específica para pedir direcciones.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'How do you ask for the price of something?', 'opcion_multiple', '["How much is it?", "How many are there?", "Where is it?", "What is it?"]', 'How much is it?', 'Frase utilizada para preguntar por el costo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'If someone says ''I''m feeling sick.'', what does it mean?', 'opcion_multiple', '["They are happy.", "They are tired.", "They are unwell.", "They are excited."]', 'They are unwell.', '''Feeling sick'' significa sentirse mal físicamente.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Which sentence is correct?', 'opcion_multiple', '["She don''t like pizza.", "She doesn''t likes pizza.", "She doesn''t like pizza.", "Doesn''t she like pizza?"]', 'She doesn''t like pizza.', 'La forma correcta del verbo en tercera persona del singular negativo es ''doesn''t like''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'What is the past tense of ''buy''?', 'opcion_multiple', '["buyed", "bought", "buyt", "byed"]', 'bought', '''Bought'' es el verbo irregular pasado de ''buy''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Which sentence asks for permission?', 'opcion_multiple', '["Can I go outside?", "I can swim.", "He can drive.", "She could sing."]', 'Can I go outside?', '''Can I...'' se usa para pedir permiso.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'What does ''It''s raining heavily'' mean?', 'opcion_multiple', '["It''s sunny.", "It''s snowing.", "There is light rain.", "There is strong rain."]', 'There is strong rain.', '''Heavily'' indica intensidad, por lo tanto, lluvia fuerte.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Which word is a fruit?', 'opcion_multiple', '["Carrot", "Potato", "Apple", "Chicken"]', 'Apple', '''Apple'' es una fruta.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'Which word is a mode of transport?', 'opcion_multiple', '["Tree", "Train", "Mountain", "River"]', 'Train', '''Train'' es un medio de transporte.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (14, 'What is the opposite of ''old''?', 'opcion_multiple', '["Young", "Big", "Small", "Happy"]', 'Young', 'La palabra opuesta a ''old'' (viejo) es ''young'' (joven).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, '¿Qué función se usa para sumar un rango de celdas?', 'opcion_multiple', '["PROMEDIO", "SUMA", "CONTAR", "MAX"]', 'SUMA', 'SUMA agrega todos los números en un rango de celdas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La función BUSCARV sirve para:', 'opcion_multiple', '["Buscar verticalmente en una tabla", "Buscar horizontalmente", "Ordenar datos", "Filtrar datos"]', 'Buscar verticalmente en una tabla', 'BUSCARV busca un valor en la primera columna y devuelve un valor en la misma fila.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, '¿Cuál es el resultado de =SI(A1>10,\\"Mayor\\",\\"Menor\\") si A1=15?', 'opcion_multiple', '["Mayor", "Menor", "10", "15"]', 'Mayor', 'Como 15>10 es VERDADERO, devuelve \\"Mayor\\".', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La función PROMEDIO calcula:', 'opcion_multiple', '["La suma total", "La media aritmética", "El valor máximo", "El valor mínimo"]', 'La media aritmética', 'Calcula el promedio (media aritmética) de los argumentos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, '¿Qué símbolo se usa para referencias absolutas?', 'opcion_multiple', '["$", "#", "@", "&"]', '$', '$A$1 crea una referencia absoluta que no cambia al copiar.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La función CONTAR cuenta:', 'opcion_multiple', '["Todas las celdas", "Solo celdas con números", "Solo celdas con texto", "Celdas vacías"]', 'Solo celdas con números', 'CONTAR solo cuenta celdas que contienen números.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, '=CONCATENAR(A1,\\" \\",B1) sirve para:', 'opcion_multiple', '["Sumar A1 y B1", "Unir texto de A1 y B1", "Restar A1 de B1", "Dividir A1 entre B1"]', 'Unir texto de A1 y B1', 'Concatena (une) textos de diferentes celdas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La función MAX devuelve:', 'opcion_multiple', '["El valor mínimo", "El valor máximo", "El promedio", "La suma"]', 'El valor máximo', 'Devuelve el valor más grande de un conjunto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, '¿Qué hace la función MIN?', 'opcion_multiple', '["Busca el máximo", "Busca el mínimo", "Calcula promedio", "Cuenta celdas"]', 'Busca el mínimo', 'Devuelve el valor más pequeño de un conjunto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La función HOY() devuelve:', 'opcion_multiple', '["La hora actual", "La fecha actual", "El día de la semana", "El mes actual"]', 'La fecha actual', 'Devuelve la fecha actual del sistema.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, '¿Qué función cuenta celdas que cumplen un criterio?', 'opcion_multiple', '["CONTAR", "CONTAR.SI", "CONTARA", "SUMAR.SI"]', 'CONTAR.SI', 'CONTAR.SI cuenta celdas que cumplen una condición específica.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'SUMAR.SI(A1:A10,\\">5\\") suma:', 'opcion_multiple', '["Todos los valores", "Solo valores mayores a 5", "Solo valores menores a 5", "Valores iguales a 5"]', 'Solo valores mayores a 5', 'Suma solo las celdas que cumplen el criterio >5.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La función SI anidada permite:', 'opcion_multiple', '["Una sola condición", "Múltiples condiciones", "Sin condiciones", "Solo 2 condiciones"]', 'Múltiples condiciones', 'Permite evaluar múltiples condiciones una dentro de otra.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, '¿Qué hace la función Y()?', 'opcion_multiple', '["Devuelve VERDADERO si todas las condiciones son verdaderas", "Devuelve VERDADERO si alguna es verdadera", "Devuelve FALSO siempre", "Suma condiciones"]', 'Devuelve VERDADERO si todas las condiciones son verdaderas', 'Y() devuelve VERDADERO solo si TODAS las condiciones son verdaderas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La función O() devuelve VERDADERO si:', 'opcion_multiple', '["Todas son verdaderas", "Al menos una es verdadera", "Ninguna es verdadera", "Son iguales"]', 'Al menos una es verdadera', 'O() devuelve VERDADERO si ALGUNA condición es verdadera.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'BUSCARH busca:', 'opcion_multiple', '["Verticalmente", "Horizontalmente", "En diagonal", "En 3D"]', 'Horizontalmente', 'BUSCARH busca en la primera fila y devuelve de la misma columna.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La función COINCIDIR devuelve:', 'opcion_multiple', '["El valor buscado", "La posición del valor", "El texto", "La suma"]', 'La posición del valor', 'Devuelve la posición relativa de un elemento en un rango.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'INDICE(matriz,fila,columna) sirve para:', 'opcion_multiple', '["Crear matriz", "Obtener valor de una posición", "Sumar matriz", "Contar matriz"]', 'Obtener valor de una posición', 'Devuelve el valor de una celda en la intersección de fila y columna.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La función TEXTO(A1,\\"dd/mm/aaaa\\"):', 'opcion_multiple', '["Convierte fecha a texto con formato", "Suma fechas", "Resta fechas", "Compara fechas"]', 'Convierte fecha a texto con formato', 'Convierte un valor a texto con el formato especificado.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, '¿Qué hace ESPACIOS(A1)?', 'opcion_multiple', '["Agrega espacios", "Elimina espacios extras", "Cuenta espacios", "Reemplaza espacios"]', 'Elimina espacios extras', 'Elimina todos los espacios del texto excepto los espacios simples entre palabras.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'BUSCARX es mejor que BUSCARV porque:', 'opcion_multiple', '["Es más rápida", "Busca en cualquier dirección", "Solo funciona en inglés", "Es más antigua"]', 'Busca en cualquier dirección', 'BUSCARX puede buscar en cualquier dirección y es más flexible.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La función FILTRAR() sirve para:', 'opcion_multiple', '["Ordenar datos", "Filtrar datos dinámicamente", "Eliminar datos", "Copiar datos"]', 'Filtrar datos dinámicamente', 'Filtra un rango de datos basándose en criterios definidos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'UNICOS() devuelve:', 'opcion_multiple', '["Valores duplicados", "Valores únicos sin duplicados", "La suma", "El promedio"]', 'Valores únicos sin duplicados', 'Devuelve una lista de valores únicos de un rango.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'ORDENAR(matriz,columna,orden) sirve para:', 'opcion_multiple', '["Filtrar", "Ordenar dinámicamente", "Buscar", "Sumar"]', 'Ordenar dinámicamente', 'Ordena el contenido de un rango o matriz.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La función SECUENCIA(filas,columnas) genera:', 'opcion_multiple', '["Texto aleatorio", "Una matriz de números secuenciales", "Fechas", "Gráficos"]', 'Una matriz de números secuenciales', 'Genera una lista de números secuenciales en una matriz.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'SI.ERROR(valor,valor_si_error) sirve para:', 'opcion_multiple', '["Crear errores", "Manejar errores elegantemente", "Ignorar errores", "Multiplicar errores"]', 'Manejar errores elegantemente', 'Devuelve un valor personalizado si la fórmula genera un error.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La función ELEGIR(num,valor1,valor2,...):', 'opcion_multiple', '["Elige un valor de la lista según el índice", "Suma valores", "Concatena valores", "Ordena valores"]', 'Elige un valor de la lista según el índice', 'Selecciona un valor de la lista basándose en el número de índice.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'DESREF(celda,filas,columnas,alto,ancho) devuelve:', 'opcion_multiple', '["Una referencia desplazada", "Un valor fijo", "Un error", "Texto"]', 'Una referencia desplazada', 'Devuelve una referencia a un rango desplazado desde una celda inicial.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La función TASA() calcula:', 'opcion_multiple', '["Interés simple", "Tasa de interés por periodo", "Pago total", "Valor futuro"]', 'Tasa de interés por periodo', 'Calcula la tasa de interés por periodo de una anualidad.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'PAGO(tasa,nper,va) calcula:', 'opcion_multiple', '["El pago periódico de un préstamo", "El interés total", "El capital", "La tasa"]', 'El pago periódico de un préstamo', 'Calcula el pago de un préstamo basado en pagos constantes y tasa constante.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Una tabla dinámica sirve para:', 'opcion_multiple', '["Solo mostrar datos", "Resumir y analizar grandes cantidades de datos", "Eliminar datos", "Crear gráficos"]', 'Resumir y analizar grandes cantidades de datos', 'Permite resumir, analizar, explorar y presentar datos de resumen.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Los campos de una tabla dinámica se organizan en:', 'opcion_multiple', '["Filas, columnas, valores y filtros", "Solo filas y columnas", "Solo valores", "Solo filtros"]', 'Filas, columnas, valores y filtros', 'Cuatro áreas: Filtros, Columnas, Filas y Valores.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Para actualizar una tabla dinámica se debe:', 'opcion_multiple', '["Borrar y crear de nuevo", "Hacer clic en Actualizar", "Esperar automáticamente", "Reiniciar Excel"]', 'Hacer clic en Actualizar', 'Se actualiza con clic derecho > Actualizar o pestaña Analizar > Actualizar.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La segmentación de datos permite:', 'opcion_multiple', '["Filtrar visualmente tablas dinámicas", "Ordenar datos", "Sumar datos", "Graficar datos"]', 'Filtrar visualmente tablas dinámicas', 'Botones visuales para filtrar datos en tablas dinámicas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Un campo calculado en tabla dinámica permite:', 'opcion_multiple', '["Crear fórmulas personalizadas", "Eliminar campos", "Ocultar campos", "Mover campos"]', 'Crear fórmulas personalizadas', 'Permite crear cálculos personalizados con los datos existentes.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Agrupar fechas en tabla dinámica permite:', 'opcion_multiple', '["Solo ver días", "Agrupar por meses, trimestres, años", "Eliminar fechas", "Sumar fechas"]', 'Agrupar por meses, trimestres, años', 'Agrupa automáticamente por períodos de tiempo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'El formato de número en valores de tabla dinámica:', 'opcion_multiple', '["No se puede cambiar", "Se puede personalizar", "Siempre es moneda", "Siempre es porcentaje"]', 'Se puede personalizar', 'Se puede configurar el formato de número en Configuración de campo de valor.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Mostrar valores como en tabla dinámica permite:', 'opcion_multiple', '["Solo suma", "Porcentajes, diferencias, acumulados", "Solo promedio", "Solo conteo"]', 'Porcentajes, diferencias, acumulados', 'Muestra valores como % del total, diferencia, ejecución, etc.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Una tabla dinámica conectada a Power Pivot permite:', 'opcion_multiple', '["Solo datos simples", "Manejar millones de filas y relaciones", "Solo texto", "Solo gráficos"]', 'Manejar millones de filas y relaciones', 'Power Pivot permite modelos de datos avanzados con millones de filas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Actualizar automáticamente al abrir el libro requiere:', 'opcion_multiple', '["Nada especial", "Configurar propiedades de la tabla", "Macro obligatoria", "VBA complejo"]', 'Configurar propiedades de la tabla', 'En Opciones de tabla dinámica > marcar ''Actualizar al abrir el archivo''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Un gráfico de líneas es ideal para:', 'opcion_multiple', '["Comparar categorías", "Mostrar tendencias en el tiempo", "Mostrar partes de un todo", "Distribución de datos"]', 'Mostrar tendencias en el tiempo', 'Muestra tendencias y cambios a lo largo del tiempo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Un gráfico circular muestra:', 'opcion_multiple', '["Tendencias", "Partes de un todo (porcentajes)", "Comparaciones", "Distribución"]', 'Partes de un todo (porcentajes)', 'Muestra la contribución de cada valor al total.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Un histograma muestra:', 'opcion_multiple', '["Frecuencia de datos", "Tendencias", "Porcentajes", "Relaciones"]', 'Frecuencia de datos', 'Muestra la distribución de frecuencia de los datos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Los minigráficos (sparklines) son:', 'opcion_multiple', '["Gráficos grandes", "Gráficos pequeños en una celda", "Tablas", "Fórmulas"]', 'Gráficos pequeños en una celda', 'Minigráficos que caben en una sola celda para mostrar tendencias.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Un gráfico combinado permite:', 'opcion_multiple', '["Solo un tipo de gráfico", "Combinar dos tipos (ej. columnas y líneas)", "Solo columnas", "Solo líneas"]', 'Combinar dos tipos (ej. columnas y líneas)', 'Combina dos o más tipos de gráficos en uno solo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'El eje secundario en gráficos sirve para:', 'opcion_multiple', '["Mostrar otra escala de valores", "Eliminar datos", "Ocultar datos", "Sumar datos"]', 'Mostrar otra escala de valores', 'Permite graficar series con escalas muy diferentes.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Las etiquetas de datos muestran:', 'opcion_multiple', '["Solo el título", "Valores específicos en el gráfico", "Solo leyenda", "Solo ejes"]', 'Valores específicos en el gráfico', 'Muestran los valores exactos en cada punto del gráfico.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Un gráfico de dispersión (XY) muestra:', 'opcion_multiple', '["Relación entre dos variables numéricas", "Solo una variable", "Texto", "Fechas"]', 'Relación entre dos variables numéricas', 'Muestra la relación entre valores numéricos en dos series.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Los filtros de gráfico permiten:', 'opcion_multiple', '["No filtrar", "Filtrar datos visibles en el gráfico", "Eliminar gráfico", "Copiar gráfico"]', 'Filtrar datos visibles en el gráfico', 'Filtran qué datos se muestran en el gráfico dinámicamente.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Un mapa 3D en Excel requiere:', 'opcion_multiple', '["Solo texto", "Datos geográficos (países, ciudades)", "Solo números", "Solo fechas"]', 'Datos geográficos (países, ciudades)', 'Necesita datos geográficos para crear visualizaciones en mapa.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'El formato condicional permite:', 'opcion_multiple', '["Solo colorear", "Aplicar formato basado en condiciones", "Solo bordes", "Solo fuentes"]', 'Aplicar formato basado en condiciones', 'Aplica formato automáticamente cuando se cumplen condiciones.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Las barras de datos en formato condicional:', 'opcion_multiple', '["Son gráficos separados", "Muestran barras dentro de las celdas", "Son tablas", "Son fórmulas"]', 'Muestran barras dentro de las celdas', 'Muestran barras proporcionales al valor dentro de la celda.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Las escalas de color aplican:', 'opcion_multiple', '["Un solo color", "Degradado de colores según valor", "Solo rojo", "Solo verde"]', 'Degradado de colores según valor', 'Aplica un degradado de 2 o 3 colores según el valor.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Los conjuntos de iconos muestran:', 'opcion_multiple', '["Solo números", "Iconos según rangos de valores", "Solo texto", "Solo fechas"]', 'Iconos según rangos de valores', 'Muestra iconos (semáforos, flechas, etc.) según el valor.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Una fórmula en formato condicional permite:', 'opcion_multiple', '["Condiciones simples", "Condiciones personalizadas complejas", "Sin condiciones", "Solo igualdad"]', 'Condiciones personalizadas complejas', 'Permite crear reglas personalizadas con fórmulas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Resaltar celdas que contienen texto específico usa:', 'opcion_multiple', '["Solo números", "Regla de texto que contiene", "Solo fechas", "Solo colores"]', 'Regla de texto que contiene', 'Regla predefinida para buscar texto específico.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Los valores duplicados se pueden resaltar con:', 'opcion_multiple', '["No se puede", "Formato condicional > Valores duplicados", "Solo manualmente", "Solo con VBA"]', 'Formato condicional > Valores duplicados', 'Regla predefinida para identificar duplicados.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'El formato condicional se puede basar en:', 'opcion_multiple', '["Solo el valor de la celda", "Otra celda o rango", "Solo texto", "Solo fechas"]', 'Otra celda o rango', 'Puede usar fórmulas que referencien otras celdas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Administrar reglas de formato condicional permite:', 'opcion_multiple', '["Solo crear", "Editar, eliminar y ordenar reglas", "Solo ver", "Solo copiar"]', 'Editar, eliminar y ordenar reglas', 'Permite gestionar todas las reglas aplicadas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Detener si es verdadero en formato condicional:', 'opcion_multiple', '["No existe", "Detiene evaluación de reglas siguientes", "Siempre evalúa todo", "Solo en tablas"]', 'Detiene evaluación de reglas siguientes', 'Cuando es VERDADERO, no evalúa reglas adicionales.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La validación de datos permite:', 'opcion_multiple', '["Solo texto", "Restringir lo que se puede escribir", "Solo números", "Solo fechas"]', 'Restringir lo que se puede escribir', 'Restringe el tipo de datos o valores que los usuarios pueden escribir.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Una lista de validación crea:', 'opcion_multiple', '["Un gráfico", "Una lista desplegable", "Una tabla", "Un formulario"]', 'Una lista desplegable', 'Crea un menú desplegable con opciones predefinidas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Validación con número entero entre 1 y 10:', 'opcion_multiple', '["No se puede", "Permite solo números del 1 al 10", "Permite cualquier número", "Permite texto"]', 'Permite solo números del 1 al 10', 'Restringe a números enteros dentro del rango especificado.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'El mensaje de entrada en validación:', 'opcion_multiple', '["No existe", "Aparece al seleccionar la celda", "Siempre está visible", "Solo en impresión"]', 'Aparece al seleccionar la celda', 'Muestra información cuando el usuario selecciona la celda.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'La alerta de error en validación muestra:', 'opcion_multiple', '["Nada", "Mensaje cuando se ingresa dato inválido", "Siempre", "Solo al guardar"]', 'Mensaje cuando se ingresa dato inválido', 'Aparece cuando el usuario intenta escribir un valor no válido.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Validación con fecha posterior a hoy:', 'opcion_multiple', '["No se puede", "=HOY()", "Solo fechas pasadas", "Solo texto"]', '=HOY()', 'Usa fórmula =HOY() para validar fechas futuras.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Validación personalizada con fórmula permite:', 'opcion_multiple', '["Solo listas", "Cualquier condición lógica", "Solo números", "Solo texto"]', 'Cualquier condición lógica', 'Permite crear reglas complejas con fórmulas.', 'intermedio');
