INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Quitar validación de datos:', 'opcion_multiple', '["No se puede", "Datos > Validación > Borrar todos", "Solo con VBA", "Solo borrando celda"]', 'Datos > Validación > Borrar todos', 'Se quita desde Validación de datos > Borrar todos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Validación que depende de otra celda usa:', 'opcion_multiple', '["No se puede", "Referencia a otra celda o rango", "Solo valores fijos", "Solo texto"]', 'Referencia a otra celda o rango', 'Puede usar referencias a otros rangos para listas dependientes.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Una macro es:', 'opcion_multiple', '["Una fórmula", "Una grabación de acciones automatizadas", "Un gráfico", "Una tabla"]', 'Una grabación de acciones automatizadas', 'Secuencia de comandos que automatiza tareas repetitivas.', 'intermedio');
