INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Las macros se guardan en:', 'opcion_multiple', '["Solo en el libro activo", "Libro de macros personal o libro actual", "Solo en disco", "No se guardan"]', 'Libro de macros personal o libro actual', 'Pueden guardarse en el libro actual o en el libro de macros personal.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Un botón asignado a macro permite:', 'opcion_multiple', '["No ejecutar", "Ejecutar macro con un clic", "Solo ver macro", "Solo editar"]', 'Ejecutar macro con un clic', 'Ejecuta la macro asignada al hacer clic.', 'intermedio');
