INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Range(\\"A1\\").Value = 10 escribe:', 'opcion_multiple', '["Lee A1", "Escribe 10 en A1", "Borra A1", "Formato de A1"]', 'Escribe 10 en A1', 'Asigna el valor 10 a la celda A1.', 'intermedio');
