INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'If ... Then ... Else permite:', 'opcion_multiple', '["No decidir", "Tomar decisiones en el código", "Solo sumar", "Solo restar"]', 'Tomar decisiones en el código', 'Estructura condicional para decisiones.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Power Query sirve para:', 'opcion_multiple', '["Solo gráficos", "Transformar y limpiar datos", "Solo fórmulas", "Solo impresión"]', 'Transformar y limpiar datos', 'Herramienta ETL (Extraer, Transformar, Cargar) de datos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Desde Texto/CSV en Power Query importa:', 'opcion_multiple', '["Solo Excel", "Archivos de texto y CSV", "Solo PDF", "Solo imágenes"]', 'Archivos de texto y CSV', 'Importa datos desde archivos de texto delimitados.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Eliminar columnas en Power Query:', 'opcion_multiple', '["No se puede", "Clic derecho > Quitar", "Solo con fórmulas", "Solo manualmente"]', 'Clic derecho > Quitar', 'Seleccionar columna > clic derecho > Quitar.', 'intermedio');
