INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Anexar consultas en Power Query:', 'opcion_multiple', '["No se puede", "Combina tablas verticalmente", "Solo horizontal", "Solo copia"]', 'Combina tablas verticalmente', 'Agrega filas de una tabla a otra (unión vertical).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Combinar consultas (Merge) es:', 'opcion_multiple', '["Unión vertical", "Unión horizontal (como BUSCARV)", "Solo copia", "Solo filtro"]', 'Unión horizontal (como BUSCARV)', 'Combina tablas horizontalmente basándose en columna común.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Cerrar y cargar en Power Query:', 'opcion_multiple', '["No guarda", "Aplica transformaciones y carga a Excel", "Solo guarda", "Solo cierra"]', 'Aplica transformaciones y carga a Excel', 'Ejecuta todas las transformaciones y carga los datos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Los pasos aplicados en Power Query:', 'opcion_multiple', '["No se ven", "Se registran y pueden editarse", "Son permanentes", "No se pueden cambiar"]', 'Se registran y pueden editarse', 'Cada transformación se guarda como paso editable.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Actualizar desde Power Query:', 'opcion_multiple', '["No actualiza", "Refresca datos desde origen", "Solo manualmente", "Borra datos"]', 'Refresca datos desde origen', 'Actualiza datos desde el origen aplicando transformaciones.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'Power Query puede conectarse a:', 'opcion_multiple', '["Solo Excel", "Múltiples fuentes (BD, web, archivos)", "Solo texto", "Solo CSV"]', 'Múltiples fuentes (BD, web, archivos)', 'Conecta a bases de datos, web, archivos, carpetas, etc.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'VF(tasa,nper,pago,va) calcula:', 'opcion_multiple', '["Valor presente", "Valor futuro de una inversión", "Tasa de interés", "Pago periódico"]', 'Valor futuro de una inversión', 'Calcula el valor futuro de una inversión con pagos constantes.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'VA(tasa,nper,pago,vf) calcula:', 'opcion_multiple', '["Valor futuro", "Valor presente", "Tasa", "Pago"]', 'Valor presente', 'Calcula el valor presente de una inversión.', 'intermedio');
