INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'HALLAR es similar a ENCONTRAR pero:', 'opcion_multiple', '["No distingue mayúsculas/minúsculas", "Distingue mayúsculas", "Solo números", "Solo texto"]', 'No distingue mayúsculas/minúsculas', 'No distingue entre mayúsculas y minúsculas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'SUSTITUIR(texto,texto_original,texto_nuevo):', 'opcion_multiple', '["No sustituye", "Reemplaza texto específico", "Solo agrega", "Solo borra"]', 'Reemplaza texto específico', 'Reemplaza texto específico dentro de una cadena.', 'intermedio');
