INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'MAYUSC(texto) convierte a:', 'opcion_multiple', '["Minúsculas", "MAYÚSCULAS", "Tipo Oración", "No cambia"]', 'MAYÚSCULAS', 'Convierte todo el texto a mayúsculas.', 'intermedio');
