INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'REPETIR(texto,núm_veces):', 'opcion_multiple', '["No repite", "Repite texto varias veces", "Solo una vez", "Borra texto"]', 'Repite texto varias veces', 'Repite el texto el número de veces especificado.', 'intermedio');
