INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'CODIGO(texto) devuelve:', 'opcion_multiple', '["El texto", "Código ASCII del primer carácter", "Longitud", "Posición"]', 'Código ASCII del primer carácter', 'Devuelve el código numérico del primer carácter.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'CARACTER(número) devuelve:', 'opcion_multiple', '["Número", "Carácter según código ASCII", "Texto", "Longitud"]', 'Carácter según código ASCII', 'Devuelve el carácter especificado por el número de código.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (15, 'FECHA(año,mes,día) crea:', 'opcion_multiple', '["Texto", "Una fecha válida", "Número", "Hora"]', 'Una fecha válida', 'Crea un número de serie de fecha válido.', 'intermedio');
