INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'I _____ to the gym three times a week.', 'opcion_multiple', '["go", "am going", "went", "have gone"]', 'go', 'Present Simple for habits/routines.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'She _____ when I called her.', 'opcion_multiple', '["sleeps", "was sleeping", "has slept", "slept"]', 'was sleeping', 'Past Continuous for action in progress at specific time.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'They _____ in London since 2015.', 'opcion_multiple', '["live", "are living", "have lived", "lived"]', 'have lived', 'Present Perfect with ''since'' for actions from past to present.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'By next year, I _____ my degree.', 'opcion_multiple', '["finish", "will finish", "will have finished", "am finishing"]', 'will have finished', 'Future Perfect for action completed before specific future time.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'If I _____ you, I would accept the offer.', 'opcion_multiple', '["am", "was", "were", "have been"]', 'were', 'Second conditional: ''were'' for hypothetical situations.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'He _____ to work by bus every day.', 'opcion_multiple', '["go", "goes", "is going", "went"]', 'goes', 'Present Simple third person singular: goes.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'I _____ dinner when the phone rang.', 'opcion_multiple', '["cooked", "was cooking", "have cooked", "cook"]', 'was cooking', 'Past Continuous interrupted by Past Simple.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'She _____ never _____ sushi before.', 'opcion_multiple', '["has/eaten", "have/eaten", "had/eaten", "was/eating"]', 'has/eaten', 'Present Perfect for life experience with ''never''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'While I _____, my brother was watching TV.', 'opcion_multiple', '["studied", "was studying", "have studied", "study"]', 'was studying', 'Two simultaneous actions in past: both Past Continuous.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'The train _____ at 8 PM tonight.', 'opcion_multiple', '["leave", "leaves", "is leaving", "will leave"]', 'leaves', 'Present Simple for scheduled events.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'You _____ wear a helmet when riding a bike.', 'opcion_multiple', '["can", "must", "might", "could"]', 'must', '''Must'' for obligation/necessity.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '_____ I borrow your pen?', 'opcion_multiple', '["Must", "Should", "Could", "Would"]', 'Could', '''Could'' for polite requests.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'She _____ speak three languages fluently.', 'opcion_multiple', '["must", "can", "should", "would"]', 'can', '''Can'' for ability.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'You _____ see a doctor if you feel sick.', 'opcion_multiple', '["can", "should", "might", "could"]', 'should', '''Should'' for advice.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'It _____ rain later, so take an umbrella.', 'opcion_multiple', '["must", "might", "should", "can"]', 'might', '''Might'' for possibility.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'He _____ have forgotten about the meeting.', 'opcion_multiple', '["must", "can", "should", "will"]', 'must', '''Must have'' for logical deduction about the past.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'You _____ smoke in the hospital.', 'opcion_multiple', '["mustn''t", "don''t have to", "needn''t", "couldn''t"]', 'mustn''t', '''Mustn''t'' for prohibition.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'I _____ finish this report by tomorrow.', 'opcion_multiple', '["can", "must", "might", "could"]', 'must', '''Must'' for strong obligation.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '_____ you help me with this, please?', 'opcion_multiple', '["Must", "Should", "Would", "Might"]', 'Would', '''Would'' for polite requests.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'You _____ worry, everything will be fine.', 'opcion_multiple', '["mustn''t", "needn''t", "shouldn''t", "couldn''t"]', 'needn''t', '''Needn''t'' for lack of necessity.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Please _____ your shoes before entering.', 'opcion_multiple', '["take off", "put on", "get up", "turn off"]', 'take off', '''Take off'' = remove.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'I need to _____ early tomorrow.', 'opcion_multiple', '["get up", "take off", "put on", "turn on"]', 'get up', '''Get up'' = wake up and leave bed.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Can you _____ the lights, please?', 'opcion_multiple', '["turn on", "turn off", "take off", "get up"]', 'turn on', '''Turn on'' = activate.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'She _____ her mother in appearance.', 'opcion_multiple', '["takes after", "looks for", "gets on", "puts up"]', 'takes after', '''Take after'' = resemble (family member).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'I''m looking _____ to the weekend.', 'opcion_multiple', '["forward", "after", "for", "up"]', 'forward', '''Look forward to'' = anticipate with pleasure.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'He _____ smoking last year.', 'opcion_multiple', '["gave up", "gave in", "gave out", "gave away"]', 'gave up', '''Give up'' = quit/stop doing something.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Please _____ this form.', 'opcion_multiple', '["fill in", "fill up", "fill out", "fill on"]', 'fill out', '''Fill out'' = complete a form.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'I can''t _____ what he''s saying.', 'opcion_multiple', '["make up", "make out", "make in", "make for"]', 'make out', '''Make out'' = understand/hear clearly.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'She _____ a great idea.', 'opcion_multiple', '["came up with", "came across", "came into", "came from"]', 'came up with', '''Come up with'' = think of/create.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'I _____ an old friend yesterday.', 'opcion_multiple', '["ran into", "ran out", "ran over", "ran away"]', 'ran into', '''Run into'' = meet by chance.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'What is the main cause of climate change according to the text?', 'opcion_multiple', '["Natural cycles", "Human activities", "Solar radiation", "Volcanic activity"]', 'Human activities', 'Text states: ''human activities, particularly burning fossil fuels''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'What has resulted from rising temperatures?', 'opcion_multiple', '["Only sea level rise", "Multiple environmental changes", "Only melting ice", "Nothing significant"]', 'Multiple environmental changes', 'Text mentions: melting ice caps, rising sea levels, extreme weather.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'What solution does the text suggest?', 'opcion_multiple', '["Ignore the problem", "Reduce emissions and use renewable energy", "Continue using fossil fuels", "Wait for natural solutions"]', 'Reduce emissions and use renewable energy', 'Text states: ''reduce carbon emissions and transition to renewable energy''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'What is one advantage of remote work?', 'opcion_multiple', '["More isolation", "Flexibility", "Harder work-life balance", "More commuting"]', 'Flexibility', 'Text states: ''offers flexibility and eliminates commuting''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'What is a disadvantage mentioned?', 'opcion_multiple', '["Too much flexibility", "Isolation", "No commuting", "Too much office time"]', 'Isolation', 'Text mentions: ''challenges such as isolation''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'What solution are companies adopting?', 'opcion_multiple', '["Only remote work", "Only office work", "Hybrid models", "No work"]', 'Hybrid models', 'Text states: ''adopting hybrid models that combine remote and office work''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Synonym of ''happy'':', 'opcion_multiple', '["Sad", "Joyful", "Angry", "Tired"]', 'Joyful', '''Joyful'' means very happy.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Synonym of ''big'':', 'opcion_multiple', '["Small", "Tiny", "Large", "Little"]', 'Large', '''Large'' means big in size.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Synonym of ''quick'':', 'opcion_multiple', '["Slow", "Fast", "Lazy", "Late"]', 'Fast', '''Fast'' means quick/rapid.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Synonym of ''difficult'':', 'opcion_multiple', '["Easy", "Simple", "Hard", "Soft"]', 'Hard', '''Hard'' means difficult.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Synonym of ''begin'':', 'opcion_multiple', '["End", "Finish", "Start", "Stop"]', 'Start', '''Start'' means begin.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Synonym of ''important'':', 'opcion_multiple', '["Unimportant", "Significant", "Minor", "Trivial"]', 'Significant', '''Significant'' means important.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Synonym of ''beautiful'':', 'opcion_multiple', '["Ugly", "Attractive", "Plain", "Ordinary"]', 'Attractive', '''Attractive'' means beautiful/pretty.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Synonym of ''intelligent'':', 'opcion_multiple', '["Stupid", "Smart", "Slow", "Dull"]', 'Smart', '''Smart'' means intelligent.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Synonym of ''rich'':', 'opcion_multiple', '["Poor", "Wealthy", "Broke", "Needy"]', 'Wealthy', '''Wealthy'' means rich/having money.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Synonym of ''famous'':', 'opcion_multiple', '["Unknown", "Well-known", "Obscure", "Anonymous"]', 'Well-known', '''Well-known'' means famous.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Active: ''They built this house in 1990.'' Passive:', 'opcion_multiple', '["This house built in 1990", "This house was built in 1990", "This house is built in 1990", "This house has built in 1990"]', 'This house was built in 1990', 'Past Simple Passive: was/were + past participle.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Active: ''Someone stole my bike.'' Passive:', 'opcion_multiple', '["My bike stole", "My bike was stolen", "My bike is stolen", "My bike has stolen"]', 'My bike was stolen', 'Past Simple Passive for unknown agent.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Active: ''They will announce the results tomorrow.'' Passive:', 'opcion_multiple', '["The results will announce tomorrow", "The results will be announced tomorrow", "The results are announced tomorrow", "The results announce tomorrow"]', 'The results will be announced tomorrow', 'Future Passive: will be + past participle.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Active: ''People speak English worldwide.'' Passive:', 'opcion_multiple', '["English speaks worldwide", "English is spoken worldwide", "English was spoken worldwide", "English has spoken worldwide"]', 'English is spoken worldwide', 'Present Simple Passive: am/is/are + past participle.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Active: ''The chef is preparing dinner.'' Passive:', 'opcion_multiple', '["Dinner is preparing", "Dinner is being prepared", "Dinner was prepared", "Dinner prepares"]', 'Dinner is being prepared', 'Present Continuous Passive: is/are being + past participle.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Active: ''They have completed the project.'' Passive:', 'opcion_multiple', '["The project has completed", "The project has been completed", "The project was completed", "The project completes"]', 'The project has been completed', 'Present Perfect Passive: has/have been + past participle.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Passive is used when:', 'opcion_multiple', '["The agent is important", "The agent is unknown/unimportant", "Always use active", "Never use passive"]', 'The agent is unknown/unimportant', 'Passive emphasizes the action, not who did it.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''By'' in passive voice introduces:', 'opcion_multiple', '["The object", "The agent", "The time", "The place"]', 'The agent', '''By'' introduces who/what performed the action.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Active: ''You must finish this today.'' Passive:', 'opcion_multiple', '["This must finish today", "This must be finished today", "This is finished today", "This finishes today"]', 'This must be finished today', 'Modal Passive: modal + be + past participle.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Which is correct passive?', 'opcion_multiple', '["The letter was send", "The letter was sent", "The letter sent", "The letter is send"]', 'The letter was sent', 'Past participle of ''send'' is ''sent''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Antonym of ''hot'':', 'opcion_multiple', '["Warm", "Cold", "Boiling", "Heated"]', 'Cold', '''Cold'' is opposite of hot.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Antonym of ''love'':', 'opcion_multiple', '["Like", "Hate", "Adore", "Cherish"]', 'Hate', '''Hate'' is opposite of love.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Antonym of ''win'':', 'opcion_multiple', '["Succeed", "Lose", "Triumph", "Achieve"]', 'Lose', '''Lose'' is opposite of win.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Antonym of ''always'':', 'opcion_multiple', '["Forever", "Never", "Often", "Usually"]', 'Never', '''Never'' is opposite of always.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Antonym of ''correct'':', 'opcion_multiple', '["Right", "Wrong", "Accurate", "Precise"]', 'Wrong', '''Wrong'' is opposite of correct.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Antonym of ''increase'':', 'opcion_multiple', '["Grow", "Decrease", "Rise", "Expand"]', 'Decrease', '''Decrease'' is opposite of increase.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Antonym of ''accept'':', 'opcion_multiple', '["Agree", "Reject", "Receive", "Approve"]', 'Reject', '''Reject'' is opposite of accept.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Antonym of ''brave'':', 'opcion_multiple', '["Courageous", "Cowardly", "Bold", "Fearless"]', 'Cowardly', '''Cowardly'' is opposite of brave.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Antonym of ''generous'':', 'opcion_multiple', '["Kind", "Selfish", "Giving", "Charitable"]', 'Selfish', '''Selfish'' is opposite of generous.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Antonym of ''arrive'':', 'opcion_multiple', '["Reach", "Depart", "Come", "Enter"]', 'Depart', '''Depart'' is opposite of arrive.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Zero conditional: If you heat ice, it _____.', 'opcion_multiple', '["melted", "melts", "will melt", "would melt"]', 'melts', 'Zero conditional: If + present, present (facts).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'First conditional: If it rains, I _____ home.', 'opcion_multiple', '["stay", "stayed", "will stay", "would stay"]', 'will stay', 'First conditional: If + present, will + base (real future).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Second conditional: If I _____ rich, I would travel.', 'opcion_multiple', '["am", "was", "were", "have been"]', 'were', 'Second conditional: If + past, would + base (unreal present).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Third conditional: If I _____ studied, I would have passed.', 'opcion_multiple', '["have", "had", "would have", "did"]', 'had', 'Third conditional: If + past perfect, would have + past participle (unreal past).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Mixed conditional: If I _____ harder, I would have a better job now.', 'opcion_multiple', '["worked", "had worked", "work", "would work"]', 'had worked', 'Mixed: past action (had worked) affecting present (would have).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''Unless'' means:', 'opcion_multiple', '["If", "If not", "When", "Because"]', 'If not', '''Unless'' = ''if not'' or ''except if''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Complete: ''If I were you, I _____ apologize.''', 'opcion_multiple', '["will", "would", "had", "have"]', 'would', 'Second conditional for advice: would + base.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''Provided that'' is similar to:', 'opcion_multiple', '["Unless", "If", "When", "Because"]', 'If', '''Provided that'' = ''if'' (on condition that).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'In second conditional, we use ''were'' for:', 'opcion_multiple', '["Only plural", "All persons (I/he/she/it)", "Only I", "Only they"]', 'All persons (I/he/she/it)', '''Were'' is used for all persons in hypothetical situations.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Third conditional expresses:', 'opcion_multiple', '["Real future", "Unreal past (regrets)", "Facts", "Habits"]', 'Unreal past (regrets)', 'Third conditional: impossible past situations.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Make a _____', 'opcion_multiple', '["homework", "decision", "test", "class"]', 'decision', '''Make a decision'' (not ''do a decision'').', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Do your _____', 'opcion_multiple', '["homework", "decision", "mistake", "effort"]', 'homework', '''Do homework'' (not ''make homework'').', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Take a _____', 'opcion_multiple', '["photo", "photo graph", "photography", "photoed"]', 'photo', '''Take a photo/picture''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Have a _____', 'opcion_multiple', '["shower", "show", "showered", "showing"]', 'shower', '''Have a shower'' (British) or ''take a shower'' (American).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Pay _____', 'opcion_multiple', '["attention", "attentive", "attentively", "attended"]', 'attention', '''Pay attention'' (fixed expression).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Catch a _____', 'opcion_multiple', '["cold", "ill", "sick", "disease"]', 'cold', '''Catch a cold'' (get sick).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Break a _____', 'opcion_multiple', '["leg", "legged", "legging", "legs"]', 'leg', '''Break a leg'' (injury or ''good luck'' in theater).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Keep a _____', 'opcion_multiple', '["secret", "secretly", "secrete", "secrecy"]', 'secret', '''Keep a secret'' (not tell anyone).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Save _____', 'opcion_multiple', '["time", "timing", "timed", "timer"]', 'time', '''Save time'' (not waste time).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Waste _____', 'opcion_multiple', '["money", "monied", "monies", "monetary"]', 'money', '''Waste money'' (spend unwisely).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Direct: ''I am tired.'' Reported: He said he _____ tired.', 'opcion_multiple', '["am", "is", "was", "were"]', 'was', 'Present Simple → Past Simple in reported speech.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Direct: ''I will call you.'' Reported: She said she _____ call me.', 'opcion_multiple', '["will", "would", "can", "could"]', 'would', 'Will → Would in reported speech.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Direct: ''I have finished.'' Reported: He said he _____ finished.', 'opcion_multiple', '["have", "has", "had", "having"]', 'had', 'Present Perfect → Past Perfect.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Direct: ''Can you help?'' Reported: She asked if I _____ help.', 'opcion_multiple', '["can", "could", "will", "would"]', 'could', 'Can → Could in reported speech.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Direct: ''Where do you live?'' Reported: He asked where I _____.', 'opcion_multiple', '["live", "lived", "have lived", "had lived"]', 'lived', 'Present → Past in reported questions.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Direct: ''I must go.'' Reported: She said she _____ go.', 'opcion_multiple', '["must", "had to", "have to", "has to"]', 'had to', 'Must → Had to in reported speech.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Reported speech often uses:', 'opcion_multiple', '["Same tense", "Backshift (one tense back)", "Future only", "Present only"]', 'Backshift (one tense back)', 'Tenses typically shift back in time.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''Tomorrow'' in reported speech becomes:', 'opcion_multiple', '["Tomorrow", "The next day", "Yesterday", "Today"]', 'The next day', 'Time expressions change: tomorrow → the next day.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''Here'' in reported speech becomes:', 'opcion_multiple', '["Here", "There", "Everywhere", "Nowhere"]', 'There', 'Place expressions: here → there.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Commands in reported speech use:', 'opcion_multiple', '["Say + infinitive", "Tell + object + infinitive", "Ask + if", "Say + that"]', 'Tell + object + infinitive', '''He told me to go'' (tell + object + to + verb).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'What has AI revolutionized?', 'opcion_multiple', '["Only healthcare", "Multiple industries", "Only finance", "Nothing significant"]', 'Multiple industries', 'Text states: ''numerous industries, from healthcare to finance''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'What can machine learning do?', 'opcion_multiple', '["Only store data", "Analyze data and identify patterns", "Delete data", "Ignore data"]', 'Analyze data and identify patterns', 'Text: ''analyze vast amounts of data to identify patterns and make predictions''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'What concerns are mentioned?', 'opcion_multiple', '["Only job displacement", "Multiple concerns (jobs, privacy, ethics)", "Only privacy", "No concerns"]', 'Multiple concerns (jobs, privacy, ethics)', 'Text mentions: ''job displacement, privacy, and ethical implications''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'What do experts recommend?', 'opcion_multiple', '["Unrestricted AI development", "Responsible AI development", "Stop AI development", "Ignore AI"]', 'Responsible AI development', 'Text: ''need for responsible AI development that prioritizes human welfare''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'I wish I _____ more time.', 'opcion_multiple', '["have", "had", "have had", "will have"]', 'had', '''I wish'' + past for present regrets.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'I''d rather you _____ now.', 'opcion_multiple', '["leave", "left", "leaving", "will leave"]', 'left', '''I''d rather'' + past for present/future preferences about others.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'It''s time we _____ home.', 'opcion_multiple', '["go", "went", "going", "will go"]', 'went', '''It''s time'' + past for things that should be done now.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'She suggested _____ to the cinema.', 'opcion_multiple', '["go", "going", "to go", "went"]', 'going', '''Suggest'' + gerund (verb-ing).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'He avoided _____ me.', 'opcion_multiple', '["see", "seeing", "to see", "saw"]', 'seeing', '''Avoid'' + gerund.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'I''m looking forward to _____ you.', 'opcion_multiple', '["see", "seeing", "saw", "seen"]', 'seeing', '''Look forward to'' + gerund (to is preposition here).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'Despite _____ tired, he continued working.', 'opcion_multiple', '["be", "being", "been", "to be"]', 'being', '''Despite'' + gerund/noun.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'In addition to _____ English, she speaks French.', 'opcion_multiple', '["speak", "speaking", "spoke", "spoken"]', 'speaking', '''In addition to'' + gerund.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'The book _____ I read was fascinating.', 'opcion_multiple', '["who", "which", "where", "when"]', 'which', '''Which'' for things (relative pronoun).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, 'The man _____ lives next door is friendly.', 'opcion_multiple', '["which", "who", "where", "when"]', 'who', '''Who'' for people (relative pronoun).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''Piece of cake'' means:', 'opcion_multiple', '["Delicious food", "Very easy", "Very difficult", "Expensive"]', 'Very easy', '''Piece of cake'' = very easy task.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''Break the ice'' means:', 'opcion_multiple', '["Freeze water", "Start conversation", "End relationship", "Make cold"]', 'Start conversation', '''Break the ice'' = initiate social interaction.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''Hit the books'' means:', 'opcion_multiple', '["Strike books", "Study hard", "Throw books", "Buy books"]', 'Study hard', '''Hit the books'' = study intensively.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''Under the weather'' means:', 'opcion_multiple', '["Sunny", "Feeling ill", "Outdoors", "Happy"]', 'Feeling ill', '''Under the weather'' = feeling sick/unwell.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''Cost an arm and a leg'' means:', 'opcion_multiple', '["Very cheap", "Very expensive", "Free", "Affordable"]', 'Very expensive', '''Cost an arm and a leg'' = very expensive.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''Spill the beans'' means:', 'opcion_multiple', '["Cook beans", "Reveal a secret", "Hide information", "Eat beans"]', 'Reveal a secret', '''Spill the beans'' = reveal secret information.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''Once in a blue moon'' means:', 'opcion_multiple', '["Every day", "Very rarely", "Every month", "Often"]', 'Very rarely', '''Once in a blue moon'' = very rarely.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''The ball is in your court'' means:', 'opcion_multiple', '["Play tennis", "Your decision/turn", "Sports event", "Give up"]', 'Your decision/turn', '''The ball is in your court'' = your responsibility to act.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''Bite the bullet'' means:', 'opcion_multiple', '["Shoot", "Face difficulty bravely", "Run away", "Eat metal"]', 'Face difficulty bravely', '''Bite the bullet'' = endure painful situation bravely.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (16, '''Let the cat out of the bag'' means:', 'opcion_multiple', '["Release animal", "Reveal secret accidentally", "Buy pet", "Hide information"]', 'Reveal secret accidentally', '''Let the cat out of the bag'' = reveal secret unintentionally.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Choose the most appropriate synonym for ''ephemeral'':', 'opcion_multiple', '["Permanent", "Temporary", "Intense", "Complex"]', 'Temporary', 'Ephemeral significa algo que dura muy poco, temporal.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What does the idiom ''to hit the nail on the head'' mean?', 'opcion_multiple', '["To miss the point", "To hammer a nail", "To be exactly right", "To be confused"]', 'To be exactly right', 'Significa decir o hacer exactamente lo correcto.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Which word best describes a feeling of intense enthusiasm?', 'opcion_multiple', '["Lethargy", "Apathy", "Zeal", "Skepticism"]', 'Zeal', 'Zeal significa entusiasmo o fervor intenso.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What is the opposite of ''gregarious''?', 'opcion_multiple', '["Outgoing", "Sociable", "Introverted", "Affable"]', 'Introverted', 'Gregarious significa sociable; su opuesto es introverted.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Which word means ''to make something less severe''?', 'opcion_multiple', '["Exacerbate", "Aggravate", "Mitigate", "Intensify"]', 'Mitigate', 'Mitigate significa reducir la gravedad de algo.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What does ''ubiquitous'' mean?', 'opcion_multiple', '["Rare", "Difficult", "Existing everywhere", "Expensive"]', 'Existing everywhere', 'Ubiquitous describe algo que parece estar presente en todos lados.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Choose the correct word to complete the sentence: ''The politician''s speech was full of _______ and half-truths.''', 'opcion_multiple', '["Euphemisms", "Clichés", "Equivocations", "Platitude"]', 'Equivocations', 'Equivocation implica ambigüedad intencionada o evasión de la verdad.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What is the meaning of ''nonchalant''?', 'opcion_multiple', '["Anxious", "Casual indifference", "Surprised", "Angry"]', 'Casual indifference', 'Nonchalant describe una actitud despreocupada o indiferente.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Identify the correct reported speech transformation: ''He said, \\"I might go.\\"''', 'opcion_multiple', '["He said that I might go.", "He said that he might go.", "He said that he may go.", "He said that he will go."]', 'He said that he might go.', 'En reported speech, ''might'' se mantiene o cambia a ''would go'' o ''could go''. ''I'' cambia a ''he''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Which sentence uses the conditional correctly?', 'opcion_multiple', '["If I would have known, I would have come.", "If I had known, I would have come.", "If I knew, I came.", "If I know, I come."]', 'If I had known, I would have come.', 'Esta es la estructura correcta del Third Conditional para una acción pasada hipotética.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What is the function of ''having been told'' in this sentence: ''Having been told the news, she left the room.''?', 'opcion_multiple', '["Adverbial clause of time", "Adverbial clause of reason", "Relative clause", "Noun clause"]', 'Adverbial clause of reason', 'Explica la razón por la cual ella dejó la habitación.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Choose the correct form: ''It''s high time you _______ your behavior.''', 'opcion_multiple', '["changed", "change", "had changed", "changes"]', 'changed', 'It''s high time + past subjunctive (verb in past form) para expresar que algo debería haberse hecho ya.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Which option correctly completes the sentence with an inversion?: ''_______ did she realize the mistake.''', 'opcion_multiple', '["Only then", "Then only", "Only when", "When only"]', 'Only then', 'Only then at the beginning triggers inversion: Subject + Auxiliary verb.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Identify the correct passive voice: ''The committee will consider the proposal.''', 'opcion_multiple', '["The proposal will be considered by the committee.", "The proposal will considered by the committee.", "The proposal is considered by the committee.", "Will be considered the proposal by the committee."]', 'The proposal will be considered by the committee.', 'Subject + will be + past participle + by agent.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What is the difference between ''fewer'' and ''less''?', 'opcion_multiple', '["No difference", "Fewer for countable, less for uncountable", "Less for countable, fewer for uncountable", "Fewer is always negative"]', 'Fewer for countable, less for uncountable', 'Fewer se usa con sustantivos contables (books, people), less con incontables (water, time).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Which sentence correctly uses a participle as an adjective?', 'opcion_multiple', '["The man running is fast.", "Running the man is fast.", "Fast is the man running.", "Is fast the man running?"]', 'The man running is fast.', 'Running modifica al sustantivo ''man'', describiéndolo.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'A text argues that technological advancement is a double-edged sword. What does this imply?', 'opcion_multiple', '["Technology is always beneficial", "Technology has both positive and negative aspects", "Technology is purely negative", "Technology is neutral"]', 'Technology has both positive and negative aspects', 'Una ''espada de doble filo'' simboliza un beneficio que también conlleva riesgos o desventajas.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'The author''s tone is described as ''sardonic''. What does this suggest?', 'opcion_multiple', '["Optimistic", "Pessimistic", "Mockingly sarcastic", "Sympathetic"]', 'Mockingly sarcastic', 'Sardonic implica un sarcasmo mordaz o irónico.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What does ''reading between the lines'' mean in terms of comprehension?', 'opcion_multiple', '["Reading slowly", "Understanding the literal meaning", "Inferring hidden meanings", "Looking for errors"]', 'Inferring hidden meanings', 'Implica interpretar el significado implícito o subyacente.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'A passage discusses the ''nuanced'' differences between two theories. What does ''nuanced'' imply?', 'opcion_multiple', '["Major", "Minor but significant", "Obvious", "Non-existent"]', 'Minor but significant', 'Nuanced describe diferencias sutiles pero importantes.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'An author uses ''hyperbole'' in their writing. What is their purpose?', 'opcion_multiple', '["To state facts", "To minimize importance", "To exaggerate for effect", "To confuse the reader"]', 'To exaggerate for effect', 'Hyperbole es una exageración deliberada para enfatizar.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What is the main purpose of a counterargument in a persuasive text?', 'opcion_multiple', '["To agree with the opponent", "To acknowledge opposing views and refute them", "To ignore other opinions", "To weaken the author''s stance"]', 'To acknowledge opposing views and refute them', 'Demuestra imparcialidad y fortaleza del argumento principal al abordarlo.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Which element is crucial for understanding an allegory?', 'opcion_multiple', '["Surface plot only", "Historical context", "Symbolic meaning beneath the surface", "Author''s biography"]', 'Symbolic meaning beneath the surface', 'Una alegoría es una narrativa con un significado simbólico más profundo.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'A writer employs ''stream of consciousness''. What characteristic does this technique aim to capture?', 'opcion_multiple', '["Logical arguments", "Chronological events", "The flow of thoughts and feelings", "Dialogue only"]', 'The flow of thoughts and feelings', 'Representa la fluidez natural e interna de los pensamientos de un personaje.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Which phrase is most appropriate for starting a formal letter?', 'opcion_multiple', '["Hey there,", "Hi,", "Dear Sir or Madam,", "What''s up,"]', 'Dear Sir or Madam,', 'Es impersonal y formal, adecuado cuando no se conoce el nombre del destinatario.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What is the correct way to cite a source in an academic essay?', 'opcion_multiple', '["Just mention the author", "Author, Year", "Author, Year, Page Number", "Author, Year, Title"]', 'Author, Year, Page Number', 'La cita precisa requiere el apellido del autor, año y número de página para referenciar directamente.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Which transition word best introduces a contrasting idea?', 'opcion_multiple', '["Furthermore", "Moreover", "However", "Therefore"]', 'However', 'However introduce una idea que contrasta con la anterior.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What should be avoided in formal writing?', 'opcion_multiple', '["Complex vocabulary", "Clear structure", "Contractions", "Third person perspective"]', 'Contractions', 'Las contracciones (don''t, won''t) son informales y se deben evitar.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Which sentence demonstrates parallel structure?', 'opcion_multiple', '["She likes reading, writing, and to paint.", "She likes reading, writing, and painting.", "She likes to read, to write, and painting.", "Reading, writing, and painting are liked by her."]', 'She likes reading, writing, and painting.', 'Todos los elementos en la lista deben usar la misma forma gramatical (gerundios en este caso).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What is the primary goal of a thesis statement?', 'opcion_multiple', '["To summarize the entire essay", "To state the main argument or claim", "To list all the points", "To ask a question"]', 'To state the main argument or claim', 'Presenta el punto central que el ensayo intenta probar.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'How should evidence be presented in an argumentative essay?', 'opcion_multiple', '["Opinions only", "Facts, statistics, examples, expert quotes", "Personal anecdotes only", "Rhetorical questions only"]', 'Facts, statistics, examples, expert quotes', 'La evidencia sólida respalda las afirmaciones del autor.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What is the purpose of a conclusion paragraph?', 'opcion_multiple', '["To introduce a new topic", "To repeat the introduction", "To summarize key points and restate the thesis", "To ask the reader a question"]', 'To summarize key points and restate the thesis', 'Cierra el ensayo recapitulando los argumentos principales y reafirmando la tesis.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'In a lecture, the speaker says ''Needless to say, the implications are profound.'' What does this imply?', 'opcion_multiple', '["The implications are obvious and significant", "The implications are minor", "The implications are unknown", "The speaker doubts the implications"]', 'The implications are obvious and significant', 'Needless to say implica que algo es tan evidente que no necesita ser dicho explícitamente.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'A presenter uses the phrase ''That being said, we must consider...''. What function does this serve?', 'opcion_multiple', '["To completely contradict the previous point", "To add a contrasting nuance to the previous point", "To emphasize the previous point", "To end the discussion"]', 'To add a contrasting nuance to the previous point', 'Introduce una idea que equilibra o modifica ligeramente el punto anterior.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What does ''reading the room'' mean in a speaking context?', 'opcion_multiple', '["Looking at the walls", "Understanding the audience''s mood and reactions", "Finding the exit", "Checking the time"]', 'Understanding the audience''s mood and reactions', 'Implica adaptar la comunicación según la percepción del estado de ánimo y la receptividad del público.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'Which term describes a speaker who is articulate?', 'opcion_multiple', '["Unclear", "Hesitant", "Fluent and clear", "Monotone"]', 'Fluent and clear', 'Articulate significa que expresa ideas con claridad y fluidez.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What is the significance of ''subtext'' in communication?', 'opcion_multiple', '["The literal words spoken", "The underlying meaning behind the words", "The volume of the voice", "The speed of speech"]', 'The underlying meaning behind the words', 'Subtext es el significado oculto o implícito en una conversación.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'How can a speaker establish credibility?', 'opcion_multiple', '["By interrupting others", "By citing relevant qualifications and sources", "By speaking loudly", "By avoiding eye contact"]', 'By citing relevant qualifications and sources', 'Demostrar conocimiento y apoyar con fuentes confiables genera confianza.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What is ''paraphrasing'' in the context of listening?', 'opcion_multiple', '["Repeating word-for-word", "Copying the text", "Restating the message in your own words", "Ignoring the message"]', 'Restating the message in your own words', 'Implica comprender y reformular la idea principal usando otras palabras.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (17, 'What is the role of inference in advanced listening?', 'opcion_multiple', '["To take notes", "To guess randomly", "To draw conclusions from implied information", "To listen passively"]', 'To draw conclusions from implied information', 'Implica usar la información dada para deducir significados no dichos explícitamente.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (18, 'Python es un lenguaje:', 'opcion_multiple', '["Compilado", "Interpretado", "Ensamblador", "Máquina"]', 'Interpretado', 'Python es interpretado, se ejecuta línea por línea.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (18, '¿Quién creó Python?', 'opcion_multiple', '["Bill Gates", "Guido van Rossum", "Steve Jobs", "Linus Torvalds"]', 'Guido van Rossum', 'Guido van Rossum lo creó en 1991.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (18, 'La extensión de archivos Python es:', 'opcion_multiple', '[".py", ".python", ".pt", ".p"]', '.py', 'Los archivos Python usan extensión .py', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (18, 'Para imprimir en Python se usa:', 'opcion_multiple', '["echo()", "print()", "console.log()", "write()"]', 'print()', 'print() es la función para mostrar salida.', 'intermedio');
