INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (18, '+= es:', 'opcion_multiple', '["Asignación simple", "Asignación con suma", "Comparación", "Incremento de 1"]', 'Asignación con suma', 'x += 5 es equivalente a x = x + 5', 'intermedio');
