INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (18, 'Un diccionario almacena:', 'opcion_multiple', '["Solo valores", "Pares clave-valor", "Solo claves", "Listas"]', 'Pares clave-valor', 'Almacena datos como pares clave: valor.', 'intermedio');
