INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (18, 'Las claves de diccionario deben ser:', 'opcion_multiple', '["Mutables", "Inmutables", "Solo números", "Solo strings"]', 'Inmutables', 'Deben ser inmutables (strings, números, tuplas).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (18, 'def nombre(): define:', 'opcion_multiple', '["Variable", "Función", "Clase", "Módulo"]', 'Función', 'La palabra clave def define una función.', 'intermedio');
