INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (18, 'Una función lambda es:', 'opcion_multiple', '["Nombrada", "Anónima (sin nombre)", "Siempre larga", "Sin parámetros"]', 'Anónima (sin nombre)', 'Función anónima de una línea: lambda x: x*2', 'intermedio');
